    requestid: number,
    name: string,
    loanamount: number,
    loanpurpose: string,
    income: number,
    phonenumber: number,
    postaladdress: string,
    zipcode: number,
    email: string,
    workreferences: string,
    creditreferences: string,
    checkingaccountnumber: number,
    securitynumber: number,
  ): boolean {
    /*Definition Start*/
    let existingLR: LoanRequest = l({
      logic: () =>
        getRepository(LoanRequest).find(
          (_l: any) =>
            l({
              logic: () => _l.RequestID === requestid,
              description: "l.RequestID=requestid",
            }).build().pass,
        ),
      description: "LoanRequest.allInstance()->any(l|l.RequestID=requestid)",
    }).build().pass;
    let succ: boolean = l({
      logic: () => true,
      description: "true",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
    const { errorMessage: preconditionErrorMessage, pass: isPreconditionPass } =
      l({
        logic: () => StandardOPs.oclIsTypeOf(requestid, Integer),
        description: "requestid.oclIsTypeOf(Integer)",
      })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(name, String),
          description: "name.oclIsTypeOf(String)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(loanamount, Real),
          description: "loanamount.oclIsTypeOf(Real)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(loanpurpose, String),
          description: "loanpurpose.oclIsTypeOf(String)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(income, Real),
          description: "income.oclIsTypeOf(Real)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(phonenumber, Integer),
          description: "phonenumber.oclIsTypeOf(Integer)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(postaladdress, String),
          description: "postaladdress.oclIsTypeOf(String)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(zipcode, Integer),
          description: "zipcode.oclIsTypeOf(Integer)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(email, String),
          description: "email.oclIsTypeOf(String)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(workreferences, String),
          description: "workreferences.oclIsTypeOf(String)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(creditreferences, String),
          description: "creditreferences.oclIsTypeOf(String)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(checkingaccountnumber, Integer),
          description: "checkingaccountnumber.oclIsTypeOf(Integer)",
        })
        .and({
          logic: () => StandardOPs.oclIsTypeOf(securitynumber, Integer),
          description: "securitynumber.oclIsTypeOf(Integer)",
        })
        .build();
    if (!isPreconditionPass) {
      throw new PreconditionError(preconditionErrorMessage);
    }
    /*Precondition End*/

    /*Postcondition Start*/
    let newLR: LoanRequest;
    return l()
      .if({
        logic: () =>
          l({
            logic: () => StandardOPs.oclIsUndefined(existingLR),
            description: "existingLR.oclIsUndefined()",
          }),
        description: "existingLR.oclIsUndefined()",
        then: l({
          execute: () => (newLR = new LoanRequest()),
          description: "newLR.oclIsNew()",
        })
          .and({
            execute: () => getRepository(LoanRequest).push(newLR),
            description: "LoanRequest.allInstance()->includes(newLR)",
          })
          .and({
            execute: () => (newLR.RequestID = requestid),
            description: "newLR.RequestID=requestid",
          })
          .and({
            execute: () => (newLR.Name = name),
            description: "newLR.Name=name",
          })
          .and({
            execute: () => (newLR.LoanAmount = loanamount),
            description: "newLR.LoanAmount=loanamount",
          })
          .and({
            execute: () => (newLR.LoanPurpose = loanpurpose),
            description: "newLR.LoanPurpose=loanpurpose",
          })
          .and({
            execute: () => (newLR.Income = income),
            description: "newLR.Income=income",
          })
          .and({
            execute: () => (newLR.PhoneNumber = phonenumber),
            description: "newLR.PhoneNumber=phonenumber",
          })
          .and({
            execute: () => (newLR.PostalAddress = postaladdress),
            description: "newLR.PostalAddress=postaladdress",
          })
          .and({
            execute: () => (newLR.ZipCode = zipcode),
            description: "newLR.ZipCode=zipcode",
          })
          .and({
            execute: () => (newLR.Email = email),
            description: "newLR.Email=email",
          })
          .and({
            execute: () => (newLR.WorkReferences = workreferences),
            description: "newLR.WorkReferences=workreferences",
          })
          .and({
            execute: () => (newLR.CreditReferences = creditreferences),
            description: "newLR.CreditReferences=creditreferences",
          })
          .and({
            execute: () =>
              (newLR.CheckingAccountNumber = checkingaccountnumber),
            description: "newLR.CheckingAccountNumber=checkingaccountnumber",
          })
          .and({
            execute: () => (newLR.SecurityNumber = securitynumber),
            description: "newLR.SecurityNumber=securitynumber",
          })
          .and({
            execute: () => (newLR.Status = LoanRequestStatus.SUBMITTED),
            description: "newLR.Status=LoanRequestStatus::SUBMITTED",
          })
          .and({
            execute: () => (this.CurrentLoanRequest = newLR),
            description: "self.CurrentLoanRequest=newLR",
          })
          .and({
            execute: () => succ,
            description: "result=succ",
          }),
        else: l({
